import{_ as a,c as r,o as t,ag as i}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Research & OSINT","description":"","frontmatter":{"title":"Research & OSINT"},"headers":[],"relativePath":"research/index.md","filePath":"research/index.md","lastUpdated":null}'),l={name:"research/index.md"};function s(n,e,o,h,c,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="research-osint" tabindex="-1">Research &amp; OSINT <a class="header-anchor" href="#research-osint" aria-label="Permalink to &quot;Research &amp; OSINT&quot;">​</a></h1><p>Open source intelligence, research methodologies, datasets, and analytical frameworks for conducting effective research operations. This guide is inspired by the intelligence cycle.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>Are you starting your path to improving your research skills? See this community guide for ways to begin: <a href="/research/community-recommended-pathways-research.html">Community Recommended Pathways</a></p><table tabindex="0"><thead><tr><th>Phase</th><th>Resources</th></tr></thead><tbody><tr><td>Plan &amp; Prepare</td><td><a href="/research/research-preparation.html">Research Preparation</a> • <a href="/research/research-template.html">Research Template</a></td></tr><tr><td>Gather</td><td><a href="/research/research-datasets.html">Research Datasets</a> • <a href="/research/research-tools.html">Research Tools</a></td></tr><tr><td>Process</td><td><a href="/research/research-containers.html">Research Containers</a> • <a href="/general/rstudio.html">RStudio Guide</a></td></tr><tr><td>Analyze</td><td><a href="/general/gephi.html">Gephi Guide</a> • <a href="/general/structured-analytic-techniques-sats.html">Structured Analytic Techniques</a></td></tr></tbody></table><h2 id="research-planning" tabindex="-1">Research Planning <a class="header-anchor" href="#research-planning" aria-label="Permalink to &quot;Research Planning&quot;">​</a></h2><p>Proper planning is crucial to ensure the success of any research project. This phase involves identifying the research question, formulating a hypothesis, and establishing clear objectives.</p><ul><li><a href="/research/research-preparation.html">Research Preparation Guide</a> - Full planning guide</li><li><a href="/research/research-template.html">Research Template</a> - Standard template for research documentation</li><li><a href="/research/research-tasks.html">Research Tasks</a> - Common research tasks and workflows</li></ul><p><strong>Recommended Planning Tools:</strong></p><ul><li><a href="https://apps.lib.umich.edu/rq/" target="_blank" rel="noreferrer">Goldilocker Tool</a> - Guided approach to refining research questions</li><li><a href="https://www.roobrick.org/#/" target="_blank" rel="noreferrer">ROOBRICK</a> - Collaborative COG Analysis with customizable weights</li><li><a href="https://www.mendeley.com" target="_blank" rel="noreferrer">Mendeley</a> - Organize and manage references</li><li><a href="https://app.diagrams.net/" target="_blank" rel="noreferrer">Draw.io</a> - Create mind maps (no login required)</li></ul><h2 id="gathering-data" tabindex="-1">Gathering Data <a class="header-anchor" href="#gathering-data" aria-label="Permalink to &quot;Gathering Data&quot;">​</a></h2><p>Data collection involves gathering relevant information from various sources.</p><h3 id="datasets-sources" tabindex="-1">Datasets &amp; Sources <a class="header-anchor" href="#datasets-sources" aria-label="Permalink to &quot;Datasets &amp; Sources&quot;">​</a></h3><ul><li><a href="/research/research-datasets.html">Research Datasets</a> - Curated datasets for research</li><li><a href="/research/research-datasets-maritime-sensors.html">Maritime Sensors Datasets</a> - Specialized maritime data</li><li><a href="/general/darkweb-links.html">Darkweb Links</a> - Resources for darkweb research</li><li><a href="/general/leaks.html">Leaks and Compilations</a> - Data leak resources</li><li><a href="/general/national-strategy-and-reports.html">National Strategy and Reports</a> - Government strategies and reports</li></ul><p><strong>Recommended Data Collection Tools:</strong></p><ul><li><a href="https://elicit.org/" target="_blank" rel="noreferrer">Elicit</a> - AI-powered literature review automation</li><li><a href="https://www.pai-dashboard.com/" target="_blank" rel="noreferrer">PAI-Dashboard</a> - Current events and foreign policy analysis</li><li><a href="https://www.worldcat.org" target="_blank" rel="noreferrer">WorldCat</a> - Global catalog of library collections</li><li><a href="https://datasetsearch.research.google.com" target="_blank" rel="noreferrer">Google Dataset Search</a> - Discover public datasets</li><li><a href="https://www.jstor.org" target="_blank" rel="noreferrer">JSTOR</a> - Digital library of academic resources</li></ul><h3 id="research-tools-platforms" tabindex="-1">Research Tools &amp; Platforms <a class="header-anchor" href="#research-tools-platforms" aria-label="Permalink to &quot;Research Tools &amp; Platforms&quot;">​</a></h3><ul><li><a href="/research/research-tools.html">Research Tools</a> - Platforms for gathering data</li><li><a href="/research/research-containers.html">Research Containers</a> - Containerized research environments</li><li><a href="/research/dataminr-research-tool.html">Dataminr Research Tool</a> - Using Dataminr for research</li></ul><h2 id="processing-data" tabindex="-1">Processing Data <a class="header-anchor" href="#processing-data" aria-label="Permalink to &quot;Processing Data&quot;">​</a></h2><p>Once data has been collected, it must be processed and organized for analysis.</p><p><strong>Recommended Processing Tools:</strong></p><ul><li><a href="https://cryptpad.irregularchat.com/sheet/" target="_blank" rel="noreferrer">Cryptpad</a> - E2EE spreadsheets, no login required</li><li><a href="https://osintcombine.tools/" target="_blank" rel="noreferrer">OSINTCombine</a> - Process and visualize CSV data</li><li><a href="https://openrefine.org" target="_blank" rel="noreferrer">OpenRefine</a> - Clean and transform messy data</li><li><a href="/general/rstudio.html">RStudio</a> - Statistical computing and visualization</li></ul><h2 id="analyzing-data" tabindex="-1">Analyzing Data <a class="header-anchor" href="#analyzing-data" aria-label="Permalink to &quot;Analyzing Data&quot;">​</a></h2><p>Examine processed data to identify patterns, trends, and relationships.</p><h3 id="analytical-frameworks" tabindex="-1">Analytical Frameworks <a class="header-anchor" href="#analytical-frameworks" aria-label="Permalink to &quot;Analytical Frameworks&quot;">​</a></h3><ul><li><a href="/general/pmesii-pt.html">PMESII-PT Framework</a> - Political, Military, Economic, Social, Information, Infrastructure, Physical Environment, Time</li><li><a href="/general/center-of-gravity-analysis-guide.html">Center of Gravity Analysis</a> - COG analysis methodology</li><li><a href="/general/structured-analytic-techniques-sats.html">Structured Analytic Techniques (SATs)</a> - Formal analytical methods</li><li><a href="/general/behavior-analysis.html">Behavior Analysis</a> - Understanding behavioral patterns</li></ul><p><strong>Recommended Analysis Tools:</strong></p><ul><li><a href="/general/gephi.html">Gephi</a> - Visualize and explore complex networks</li><li><a href="/general/rstudio.html">RStudio</a> - Statistical computing and graphics</li><li><a href="https://www.tableau.com" target="_blank" rel="noreferrer">Tableau</a> - Interactive data visualizations</li><li><a href="https://www.qsrinternational.com/nvivo-qualitative-data-analysis-software/home" target="_blank" rel="noreferrer">NVivo</a> - Qualitative data analysis</li></ul><h2 id="taaw-target-audience-analysis-worksheet" tabindex="-1">TAAW (Target Audience Analysis Worksheet) <a class="header-anchor" href="#taaw-target-audience-analysis-worksheet" aria-label="Permalink to &quot;TAAW (Target Audience Analysis Worksheet)&quot;">​</a></h2><ul><li><a href="/research/researching-for-a-taaw.html">Researching for a TAAW</a> - Research methodology</li><li><a href="/general/taaw-review.html">TAAW Review</a> - Reviewing and validating products</li><li><a href="/general/citating-a-taaw.html">Citating a TAAW</a> - Proper citation methods</li><li><a href="/general/creating-an-intellipedia-page-for-a-taaw.html">Creating an Intellipedia Page for a TAAW</a></li><li><a href="/general/identify-influencers-using-the-taaw.html">Identify Influencers using the TAAW</a> - Influencer identification workflow</li></ul><h2 id="archival-research" tabindex="-1">Archival Research <a class="header-anchor" href="#archival-research" aria-label="Permalink to &quot;Archival Research&quot;">​</a></h2><ul><li><a href="/research/archival-research.html">Archival Research</a> - Working with archives</li><li><a href="/research/research-citations.html">Research Citations</a> - Citation standards and methods</li></ul><h2 id="reporting-dissemination" tabindex="-1">Reporting &amp; Dissemination <a class="header-anchor" href="#reporting-dissemination" aria-label="Permalink to &quot;Reporting &amp; Dissemination&quot;">​</a></h2><p>The final step involves reporting and disseminating findings. Ensure the hypothesis is tested and results are presented clearly.</p><p><strong>Recommended Reporting Tools:</strong></p><ul><li><a href="https://www.overleaf.com" target="_blank" rel="noreferrer">Overleaf</a> - Collaborative research paper writing</li></ul><h2 id="external-learning" tabindex="-1">External Learning <a class="header-anchor" href="#external-learning" aria-label="Permalink to &quot;External Learning&quot;">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=qwA6MmbeGNo" target="_blank" rel="noreferrer">OSINT in 5 Hours</a> - Video tutorial</li></ul>',38)])])}const u=a(l,[["render",s]]);export{g as __pageData,u as default};
